// План specs/landing.md, 1.1 (кейс LND-01). Гость на https://techory.ai. Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { PRODUCT_IMAGES, fileName, openLanding, productImages, scrollAndWaitLoaded } from './landing-helpers';

test.describe('Landing — скриншоты системы (#99cf43b7)', () => {
  test('Landing shows exactly the 4 new product screenshots and each one loads #99cf43b7 @desktop @prod-safe', async ({ page, request }) => {
    // Ровно 4 картинки из /product/ с нужными именами
    await openLanding(page);
    const imgs = productImages(page);
    const srcs = await imgs.evaluateAll((els) => els.map((e) => (e as HTMLImageElement).src));
    expect(srcs.map(fileName).sort()).toEqual([...PRODUCT_IMAGES].sort());

    for (let i = 0; i < srcs.length; i++) {
      // Файл отдаётся: 200, картинка
      const res = await request.get(srcs[i]);
      expect(res.status(), srcs[i]).toBe(200);
      expect(res.headers()['content-type'], srcs[i]).toContain('image/');
      // На странице загружен: naturalWidth > 0
      await scrollAndWaitLoaded(imgs.nth(i));
    }
  });
});
